/*
 * A276791  Indicator function of (A003146 prefixed with 0).
 * https://oeis.org/A276791
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(0) = 1; a(n) = 1 if the (n-1)-th digit of the tribonacci word
 *            A080843 equals 2, otherwise a(n) = 0. The tribonacci word is
 *            generated by σ: 0→01, 1→02, 2→0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static uint8_t *trib_word = NULL;   /* array holding digits 0,1,2 of the tribonacci word */
static idx_t trib_len = 0;           /* current length of trib_word */

/* Ensure that trib_word has at least 'need' digits (indices 0 .. need-1).  */
static void ensure_trib(idx_t need)
{
    if (trib_len >= need)
        return;

    /* Initialise if this is the first call */
    if (trib_word == NULL) {
        trib_word = (uint8_t *)malloc(sizeof(uint8_t));
        trib_word[0] = 0;
        trib_len = 1;
    }

    /* Iteratively expand the word until we have enough digits */
    while (trib_len < need) {
        idx_t next_len = 0;
        /* Count required length of the next generation */
        for (idx_t i = 0; i < trib_len; ++i) {
            uint8_t v = trib_word[i];
            next_len += (v == 0 || v == 1) ? 2 : 1;  /* 0→2, 1→2, 2→1 characters */
        }

        uint8_t *new_arr = (uint8_t *)malloc(next_len * sizeof(uint8_t));
        idx_t pos = 0;
        for (idx_t i = 0; i < trib_len; ++i) {
            uint8_t v = trib_word[i];
            if (v == 0) {
                new_arr[pos++] = 0;
                new_arr[pos++] = 1;
            } else if (v == 1) {
                new_arr[pos++] = 0;
                new_arr[pos++] = 2;
            } else {            /* v == 2 */
                new_arr[pos++] = 0;
            }
        }
        free(trib_word);
        trib_word = new_arr;
        trib_len = next_len;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;              /* the first term is explicitly 1 */

    /* The (n-1)-th digit of the tribonacci word determines the value */
    ensure_trib(n);                   /* guarantee trib_word[n-1] exists */

    uint8_t val = trib_word[n - 1];
    return (seq_t)(val == 2 ? 1 : 0);
}
